starter:
static class Playlist {
    private final List<String> tracks = new ArrayList<>();

    void add(String track) {
        tracks.add(track);
    }

    List<String> tracks() {
        return Collections.unmodifiableList(tracks);
    }

    int size() {
        return tracks.size();
    }
}

tests:
Playlist p = new Playlist();
p.add("one");
p.add("two");

List<String> snapshot = p.tracks();
checkEq(snapshot, List.of("one", "two"));

p.add("three");
checkEq(snapshot, List.of("one", "two"));
checkEq(p.tracks(), List.of("one", "two", "three"));
checkEq(p.size(), 3);

List<String> first = p.tracks();
List<String> second = p.tracks();
checkEq(first, second);

boolean rejected = false;
try {
    p.tracks().add("sneaky");
} catch (UnsupportedOperationException e) {
    rejected = true;
}
check(rejected);
checkEq(p.size(), 3);

Playlist empty = new Playlist();
checkEq(empty.tracks(), List.of());

solution:
static class Playlist {
    private final List<String> tracks = new ArrayList<>();

    void add(String track) {
        tracks.add(track);
    }

    List<String> tracks() {
        return List.copyOf(tracks);
    }

    int size() {
        return tracks.size();
    }
}
